async function start(port = 0) {
  server = spawn(binary, ['-addr', '127.0.0.1:' + port, '-data', data], {
    cwd: root,
    windowsHide: true,
  });
  const child = server;
  return new Promise((resolve, reject) => {
    let log = '';
    const timer = setTimeout(() => reject(Error('EXE startup timeout')), 15000);
    child.once('error', (e) => {
      clearTimeout(timer);
      reject(e);
    });
    child.once('exit', (c) => {
      clearTimeout(timer);
      reject(Error('EXE exited ' + c));
    });
    child.stdout.on('data', (chunk) => {
      log += chunk;
      const match = log.match(/http:\/\/127\.0\.0\.1:(\d+)/);
      if (match) {
        clearTimeout(timer);
        resolve('http://127.0.0.1:' + match[1]);
      }
    });
  });
}
async function stop() {
  if (!server || server.exitCode != null) return;
  const child = server;
  await new Promise((resolve) => {
    child.once('exit', resolve);
    child.kill();
  });
  server = null;
}
async function state(page) {
  return page.evaluate(async () =>
    (
      await fetch('/api/state', {
        headers: { Authorization: 'Bearer ' + localStorage.getItem('vineyard-ee-token') },
      })
    ).json(),
  );
}
async function load(page, code, seat = 0) {
  await page.evaluate((token) => localStorage.setItem('vineyard-ee-token', token), code + seat);
  await page.reload();
  await page.waitForFunction(
    (code) =>
      document.querySelector('#code-label')?.textContent === '房间 ' + code &&
      !document.querySelector('#game').hidden,
    code,
  );
  await page.waitForFunction(() =>
    document.querySelector('#connection').textContent.includes('已连接'),
  );
}
async function guide(page) {
  const toggle = page.locator('#game [data-guide-toggle]');
  if ((await toggle.getAttribute('aria-pressed')) !== 'true') await toggle.click();
  if (await page.locator('[data-guide-skip]').count())
    await page.locator('[data-guide-skip]').click();
}
async function rules(page, current = false) {
  await page
    .locator(current ? '[data-rule-topic="current"]' : '#game [data-rules-open]')
    .first()
    .click();
  await page.locator('#rules-help-title').waitFor();
}
async function shot(page, name, fullPage = true) {
  const file = path.join(out, name + '.png');
  await page.screenshot({ path: file, fullPage });
  assert(
    await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth + 1),
    name + ' horizontal overflow',
  );
  assert(
    await page
      .locator('.guide-target')
      .evaluateAll((els) =>
        els.every(
          (e) =>
            !e.closest('[hidden]') &&
            e.getClientRects().length &&
            !e.matches(':disabled,[aria-disabled="true"]'),
        ),
      ),
    name + ' invisible/disabled target',
  );
  assert(await page.locator('img').evaluateAll(imgs => imgs.every(img => img.complete && img.naturalWidth > 0)),name+' broken image');
  screenshots.push(file);
}
async function choose(page, selector) {
  const response = page.waitForResponse(
    (r) => r.url().endsWith('/api/action') && r.request().method() === 'POST',
  );
  await page.locator(selector).click();
  const r = await response;
  assert.equal(r.status(), 200, await r.text());
}
async function waitChoice(page, kind) {
  await page.waitForFunction(async (kind) => {
    const r = await fetch('/api/state', {
      headers: { Authorization: 'Bearer ' + localStorage.getItem('vineyard-ee-token') },
    });
    return (await r.json()).pendingChoice?.kind === kind;
  }, kind);
}
