    assert.equal(stars.coins,me(starBefore).coins+3);assert.equal(stars.workers,me(starBefore).workers-1);
    await openAction(guest,'build');await click(guest,'slot','2');await click(guest,'building','trellis');
    await choose(guest,'#confirm-action');assert.equal(me(await state(guest)).coins,8);
    await host.locator('#influence-map > summary').click();
    await shot(host,'tuscany-main-board-desktop');
    await host.locator('#influence-map > summary').click();
    await guest.setViewportSize({width:390,height:844});await shot(guest,'tuscany-main-board-mobile');
    record('spring primary influence + saved extra star, public map and second-slot build discount through real UI');

    await load(host,'MAINsummer');await load(guest,'MAINsummer',1);await guide(host);
    await openAction(host,'trade');await click(host,'slot','2');
    await pick(host,'give','coins');await pick(host,'receive','vp');
    await choose(host,'#confirm-action');await waitChoice(host,'tuscany_trade');
    const tradePending=await state(host);const restartPort=Number(new URL(base).port);
    await stop();await start(restartPort);await Promise.all(pages.map(p=>p.reload()));
    await waitChoice(host,'tuscany_trade');assert.equal((await state(host)).pendingChoice.id,tradePending.pendingChoice.id);
    await pick(host,'give','vp');await pick(host,'receive','cards');
